#!/usr/bin/env python3
from __future__ import annotations

import argparse
import base64
import gzip
import hashlib
from pathlib import Path

TARGET_DEFAULT = Path("scripts/extract_japan_academy_imperial_section_evidence_v1.py")
PAYLOAD_SHA256 = "598d9f97d080af55a1cc408fb350fdc9541d4776e0c8cb869bac2d6faaf9d6cb"
PAYLOAD_B64_GZIP = ""


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--target", default=str(TARGET_DEFAULT))
    args = ap.parse_args()
    target = Path(args.target)
    raw = gzip.decompress(base64.b64decode(PAYLOAD_B64_GZIP))
    actual = hashlib.sha256(raw).hexdigest()
    if actual != PAYLOAD_SHA256:
        raise RuntimeError(f"Embedded payload SHA mismatch: expected {PAYLOAD_SHA256}, got {actual}")
    if target.exists():
        existing = hashlib.sha256(target.read_bytes()).hexdigest()
        if existing == PAYLOAD_SHA256:
            print(f"ALREADY INSTALLED: {target}")
            print(f"sha256={existing}")
            return 0
        raise RuntimeError(f"Target already exists with different SHA: {target} sha256={existing}")
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(raw)
    print(f"INSTALL OK: {target}")
    print(f"sha256={actual}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
